def fuzzy_dedup(words, threshold):
    reps = []
    for w in sorted(set(words)):
        for r in reps:
            if abs(len(r) - len(w)) <= threshold and edit_distance(w, r) <= threshold:
                break
        else:
            reps.append(w)
    return reps

sources.annotated:
def fuzzy_dedup(words: list[str], threshold: int) -> list[str]:
    reps = []
    for w in sorted(set(words)):
        for r in reps:
            if abs(len(r) - len(w)) <= threshold and edit_distance(w, r) <= threshold:
                break
        else:
            reps.append(w)
    return reps
